{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver korrekt § 37, stk. 1, 3 og 4 og vejledningens afsnit 4.3: sygehistorik, seneste journalnotater, epikriser, aktuelle symptomer, støtteafgørelser og personlig redegørelse. Journaler fremstilles som lægefagligt minimum, og redegørelsen som supplement eller som erstatning for manglende dokumentation om støtte. Svaret kræver ikke ny dokumentation ubetinget og gør ikke eksemplerne obligatoriske. Ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: sygehistorik og seneste lægeoplysninger, udrednings- og behandlingsforløb samt aktuelle symptomer, epikriser og journalnotater med støtteforanstaltninger som supplement, og personlig redegørelse. Svaret nævner også, at nyere dokumentation ofte mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende med. Tilbuddet om en tjekliste fylder ikke noget væsentligt."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til SU-bekendtgørelsen (bek. nr. 841 af 2026) og vejledning nr. 10157 af 5. oktober 2026 via en kildeliste og nummererede markeringer. De væsentlige udsagn kan knyttes til identificerbare kilder."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De angivne kilder, SU-bekendtgørelsen nr. 841 af 2026 og vejledning VEJ nr. 10157 af 05/10/2026, findes i den frosne kildeafgrænsning og er autoritative og anvendelige."
    },
    "c06_claim_source_support": {
      "label": "met",
      "reason": "Påstandene understøttes af vejledningens afsnit 4.3 og af § 37, stk. 1-4. Det gælder minimumskravet om journaler (stk. 3), aktualitet og konkret vurdering af de angivne funktionsnedsættelser (stk. 2 og 4), epikriser og journalnotater, støtteafgørelser og personlig redegørelse. Udsagnet om afvisning uden realitetsbehandling (note 7) har ikke direkte støtte i de udleverede passager, men er en uddybende bemærkning og ikke et centralt udsagn."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret siger, at ansøgningen kan afvises uden realitetsbehandling, hvis dokumentationen er for sparsom. Det har ingen støtte i de udleverede bestemmelser. § 37, stk. 5 handler om, at Udbetaling Danmark kan fastsætte en frist for yderligere dokumentation. Det er en tilføjet retsvirkning uden støtte. Svaret anfører også, at redegørelsen kan bruges, hvis der ikke findes tilstrækkelig lægefaglig dokumentation. Vejledningen siger kun, at den kan bruges, hvis der ikke er dokumentation for støtteforanstaltninger."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer, at de seneste oplysninger kan være ældre, fordi nyere dokumentation ofte mangler. Det gør eksemplerne til noget, man kan sende, og ikke til krav. Det beskriver den personlige redegørelse som supplement. Det angiver journalerne som det lægefaglige minimum. Det kunne dog have sagt tydeligere, at redegørelsen ikke ophæver minimumskravet."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er sammenhængende: først minimumskravet, derefter eksempler, aktualitet og særlige forhold ved medfødt funktionsnedsættelse, og til sidst en kort opsummering. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Hovedlinjen er præcis, med \"skal som minimum\", \"peger især på\", \"kan\" og \"typisk relevant\". Men svaret skriver, at redegørelsen kan bruges \"hvis der ikke findes tilstrækkelig lægefaglig dokumentation\". Det kan læses som en erstatning for lægefagligt indhold, og kilden siger noget andet. Svaret skriver også, at en for sparsom ansøgning \"kan blive afvist uden realitetsbehandling\", som kilderne ikke understøtter. Det gør retsvirkningen mere kategorisk, end kilderne tillader."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "yes",
      "reason": "Svaret behandler medfødt funktionsnedsættelse, og at nyere dokumentation ofte mangler. Det nævner vigtigheden af sygehistorik og seneste journalnotater samt den personlige redegørelse. Eksemplerne på diagnoser nævnes ikke, men de er ikke nødvendige for spørgsmålet."
    },
    "A35": {
      "label": "yes",
      "reason": "Svaret dækker de alternative og supplerende dokumentationsformer: epikriser, journalnotater, støtteafgørelser og skånehensyn og den personlige redegørelse, herunder at den kan indgå, hvor dokumentation ikke findes. Det tilføjer dog en upræcis bemærkning om redegørelsen ved utilstrækkelig lægefaglig dokumentation."
    }
  },
  "overall_notes": "Indholdsmæssigt stærkt svar, der dækker de kritiske elementer og kan spores til de rette kilder. Svaret tilføjer dog en usupporteret retsvirkning om afvisning uden realitetsbehandling og udvider anvendelsen af den personlige redegørelse til utilstrækkelig lægefaglig dokumentation. Det rammer C07 og C10."
}

